#!/usr/bin/env bash
set -euo pipefail

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"

echo "==> Building native coordinator"
cd "$REPO_ROOT/packages/han-rs"
cargo build --locked -p han-coordinator

echo "==> Generating build-info and embedded dashboard stubs"
cat > "$REPO_ROOT/packages/han/lib/build-info.generated.ts" << 'EOF'
// Auto-generated by release-test-gate.sh - DO NOT EDIT
export const HAN_VERSION = "0.0.0-gate";
export const COORDINATOR_SHA256: string | null = null;
export const DETECT_PLUGINS_PROMPT = "You are a plugin detector.";
EOF

cat > "$REPO_ROOT/packages/han/lib/commands/browse/embedded-dashboard.generated.ts" << 'EOF'
// Auto-generated by release-test-gate.sh - DO NOT EDIT
export const EMBEDDED_DASHBOARD_ASSETS: Record<string, string> = {};
EOF

echo "==> Installing dependencies"
cd "$REPO_ROOT/packages/han"
bun install --frozen-lockfile

echo "==> Running test gate"
bun test --max-concurrency=1
